-- supabase/sql/exam_question_bank_neet_pg_set3.sql
--
-- Third curated question-bank batch for 'NEET PG' (see exam_patterns_neet_pg.sql for the exam's
-- structure, and Sets 1-2 for the earlier batches -- same table/schema, no migration needed).
-- All-new questions, no overlap with Set 1 or Set 2.
--
-- Same format as the earlier sets: every row is format='mcq' with a single isCorrect:true option,
-- matching NEET PG's 100% single-best-response format. 16 chapters (8 Pre-/Para-Clinical
-- Sciences, 4 Clinical Medicine and Allied, 2 Surgery and Allied, 2 Obstetrics/Gynaecology/
-- Anesthesia) each get 4 questions, covering classic, high-yield MBBS/board-style facts.
--
-- Run this once in the Supabase SQL Editor, after exam_patterns_neet_pg.sql and
-- exam_question_bank_neet_pg_set1.sql / set2.sql.

insert into exam_question_bank (exam_name, subject, chapter, difficulty, format, text, options, numerical_answer, explanation) values

-- Anatomy
('NEET PG', 'Pre- and Para-Clinical Sciences', 'Anatomy', 'medium', 'mcq',
 'The brachial plexus is formed by the ventral rami of which spinal nerves?',
 '[{"text":"C1-C4","isCorrect":false},{"text":"C5-T1","isCorrect":true},{"text":"T1-T5","isCorrect":false},{"text":"L1-L5","isCorrect":false}]'::jsonb,
 null, 'The brachial plexus is formed by the ventral rami of spinal nerves C5 through T1, supplying the upper limb.'),
('NEET PG', 'Pre- and Para-Clinical Sciences', 'Anatomy', 'easy', 'mcq',
